// Catalogue of the Plateau 3D city models (MLIT, Project PLATEAU): per ward or city the best building model with textures
// (LOD2, else LOD1), 3D Tiles 1.0. Generated by scripts/build-plateau-catalog.mjs from the Plateau data catalogue
// (https://api.plateauview.mlit.go.jp/datacatalog/plateau-datasets, `composite_url`); the boxes are the root regions of the tilesets.
// The JSON (110 kB) is loaded on demand, so only a map with the layer switched on pays for it.
import type { TilesetSample } from '../ext/types';

export const PLATEAU_ATTRIBUTION = '3D都市モデル Project PLATEAU (国土交通省)';
export const PLATEAU_LICENSE = 'CC BY 4.0 (Nutzungsbedingungen der Regierung Japans 2.0)';

export interface PlateauSample extends TilesetSample {
  /** 1 or 2: level of detail of the buildings */
  lod: number;
  year: number;
  /** size of the whole model in MB (it streams in pieces) */
  sizeMb: number;
  /** prefecture and city, for the grouping and the card */
  pref: string;
  city: string;
}

interface Row { code: string; pref: string; city: string; ward: string | null; lod: number; year: number; mb: number; url: string; bbox: [number, number, number, number] }

/**
 * Geoid height N in Japan (metres, geoid above the GRS80 ellipsoid), roughly: the tiles carry ellipsoidal heights, the map sea
 * level, so a model is lowered by N. Interpolated between a few cities (inverse distance squared), good to a few metres only;
 * Tokyo (36.7 m) is checked against the tiles.
 */
const GEOID_ANCHORS: [number, number, number][] = [
  [141.35, 43.06, 30], [140.74, 40.82, 33], [141.0, 38.27, 37], [139.04, 37.92, 36], [139.7, 35.68, 36.7],
  [136.9, 35.18, 38], [135.5, 34.69, 36], [132.46, 34.39, 34], [130.4, 33.59, 31], [130.56, 31.6, 30], [127.68, 26.21, 27],
];
export function geoidHeight(lng: number, lat: number): number {
  let sum = 0;
  let weights = 0;
  for (const [x, y, n] of GEOID_ANCHORS) {
    const d2 = ((lng - x) * Math.cos((lat * Math.PI) / 180)) ** 2 + (lat - y) ** 2;
    if (d2 < 1e-6) return n;
    sum += n / d2;
    weights += 1 / d2;
  }
  return sum / weights;
}

export const toSample = (r: Row): PlateauSample => {
  const [w, s, e, n] = r.bbox;
  const center: [number, number] = [(w + e) / 2, (s + n) / 2];
  return {
    id: `plateau-${r.code}`,
    name: r.ward ? `${r.city} ${r.ward}` : r.city,
    url: r.url,
    bbox: r.bbox,
    center,
    attribution: PLATEAU_ATTRIBUTION,
    license: PLATEAU_LICENSE,
    heightOffsetM: -Math.round(geoidHeight(...center)),
    lod: r.lod, year: r.year, sizeMb: r.mb, pref: r.pref, city: r.city,
  };
};

let cached: Promise<readonly PlateauSample[]> | undefined;
/** All models, loaded once. */
export const loadPlateau = (): Promise<readonly PlateauSample[]> =>
  (cached ??= import('./plateau-catalog.json').then((m) => (m.default as Row[]).map(toSample)));
